import itertools

def get_tilings(n):
    cells = [(r, c) for r in range(n) for c in range(n)]
    def backtrack(remaining_cells):
        if not remaining_cells:
            return [[]]

        cell = remaining_cells[0]
        res = []
        r, c = cell

        # Try horizontal
        if (r, c + 1) in remaining_cells:
            new_remaining = [x for x in remaining_cells if x != cell and x != (r, c + 1)]
            for t in backtrack(new_remaining):
                res.append([(cell, (r, c + 1))] + t)

        # Try vertical
        if (r + 1, c) in remaining_cells:
            new_remaining = [x for x in remaining_cells if x != cell and x != (r + 1, c)]
            for t in backtrack(new_remaining):
                res.append([(cell, (r + 1, c))] + t)
        return res

    return backtrack(cells)

